int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, limit;
    cin >> n >> limit;
    vector<long long> memory(n);
    for (auto &x : memory) cin >> x;
    // (type, memory) pairs sorted so each type forms a contiguous, memory-sorted group
    vector<pair<long long, long long>> tasks(n);
    for (int i = 0; i < n; i++) {
        long long t;
        cin >> t;
        tasks[i] = {t, memory[i]};
    }
    sort(tasks.begin(), tasks.end());
    long long pairs = 0;
    for (size_t s = 0; s < tasks.size();) {
        size_t e = s;
        while (e < tasks.size() && tasks[e].first == tasks[s].first) e++;
        long long left = s, right = (long long)e - 1;
        while (left < right) {
            if (tasks[left].second + tasks[right].second <= limit) {
