import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long limit = nextLong();
        long[] memory = new long[n];
        for (int i = 0; i < n; i++) memory[i] = nextLong();
        // Both values are below 2^31: encode (type, memory) in one long so sorting groups by type.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = (nextLong() << 31) | memory[i];
        Arrays.sort(key);
        long mask = (1L << 31) - 1;
        long pairs = 0;
        for (int s = 0; s < n;) {
            int e = s;
            while (e < n && (key[e] >>> 31) == (key[s] >>> 31)) e++;
            int left = s, right = e - 1;
            while (left < right) {
                if ((key[left] & mask) + (key[right] & mask) <= limit) {
                    pairs++;
                    left++;
                }
                right--;
            }
            s = e;
        }
        System.out.println(n - pairs);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	limit := nextInt()
	memory := make([]int64, n)
	for i := range memory {
		memory[i] = nextInt()
	}
	// Both values are below 2^31: encode (type, memory) so sorting groups tasks by type.
	key := make([]int64, n)
	for i := range key {
		key[i] = nextInt()<<31 | memory[i]
	}
	slices.Sort(key)
	const mask = int64(1)<<31 - 1
	pairs := int64(0)
	for s := 0; s < n; {
		e := s
		for e < n && key[e]>>31 == key[s]>>31 {
			e++
		}
		left, right := s, e-1
		for left < right {
			if key[left]&mask+key[right]&mask <= limit {
				pairs++
				left++
			}
			right--
		}
		s = e
	}
	fmt.Println(int64(n) - pairs)
}
